import com.google.android.exoplayer2.util.Util
import kotlinx.coroutines.CoroutineDispatcher
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.withContext
import okhttp3.OkHttpClient
import okhttp3.Request
import java.io.ByteArrayInputStream
import java.io.IOException
import java.security.cert.CertificateException
import java.util.concurrent.Executors
import java.util.concurrent.TimeUnit
import javax.net.ssl.SSLContext
import javax.net.ssl.TrustManager
import javax.net.ssl.X509TrustManager
import kotlin.coroutines.resumeWithException
import kotlin.coroutines.suspendCoroutine

internal fun sanitizeDashManifest(manifest: String): String {
    val hasPrimaryInterkhBaseUrl = Regex("""<BaseURL>https://cdnr\.interkh\.com/[^<]+</BaseURL>""")
        .containsMatchIn(manifest)
    if (!hasPrimaryInterkhBaseUrl) return manifest

    return manifest.replace(
        Regex("""\s*<BaseURL>[^<]*interkh\.com/[^<]*</BaseURL>"""),
        ""
    )
}

class PlayerSource(
    private val context: Context,
    private val updateRepository: UpdateRepository,
    private val dispatcher: CoroutineDispatcher = Dispatchers.IO,
) {

    @get:Synchronized
    @set:Synchronized
    private var cacheFactory: CacheDataSource.Factory? = null
    private val handler = Handler(Looper.getMainLooper())

    @get:Synchronized
    @set:Synchronized
    private var downloadManager: DownloadManager? = null
    private var onUpdate: ((Float, Long, Long, Long, Int, Int) -> Unit?)? = null
    private val downloadListener = object : DownloadManager.Listener {
        override fun onDownloadChanged(
            downloadManager: DownloadManager,
            download: Download,
            finalException: Exception?
        ) {
            onUpdate?.invoke(
                download.percentDownloaded,
                download.bytesDownloaded,
                download.startTimeMs,
                download.updateTimeMs,
                download.state,
                downloadManager.currentDownloads.size
            )
        }
